import { db } from "./supabase-typed.js";
import { writeOneRow } from "@ai-matrx/data/db";
import { ensureOrgId } from "../../../host/org.js";
async function getCurrentPlan(conversationId) {
  const { data, error } = await db.schema("chat").from("agent_plan").select("*").eq("conversation_id", conversationId).is("deleted_at", null).neq("status", "superseded").order("updated_at", { ascending: false }).limit(1).maybeSingle();
  if (error) throw error;
  return data ?? null;
}
async function listPlansForConversation(conversationId) {
  const { data, error } = await db.schema("chat").from("agent_plan").select("*").eq("conversation_id", conversationId).is("deleted_at", null).order("updated_at", { ascending: false });
  if (error) throw error;
  return data ?? [];
}
async function createPlan(input) {
  await db.schema("chat").from("agent_plan").update({ status: "superseded" }).eq("conversation_id", input.conversation_id).is("deleted_at", null).neq("status", "superseded");
  const { data, error } = await db.schema("chat").from("agent_plan").insert({
    // `created_by` is stamped by the `_stamp_actor` trigger — never client-set.
    // org-filter: write-target writes into the organization the person is working in; no list reads it
    organization_id: await ensureOrgId(void 0),
    conversation_id: input.conversation_id,
    title: input.title,
    steps: input.steps,
    reasoning: input.reasoning ?? null,
    domains: input.domains ?? null,
    estimated_minutes: input.estimated_minutes ?? null,
    status: "proposed"
  }).select("*").single();
  if (error) throw error;
  return data;
}
async function setPlanStatus(planId, status) {
  const { data, error } = await writeOneRow(
    db.schema("chat").from("agent_plan").update({ status }).eq("id", planId).select("*"),
    { action: "update", noun: "agent plan" }
  );
  if (error) throw error;
  return data;
}
async function clearPlan(conversationId) {
  const { error } = await db.schema("chat").from("agent_plan").update({ deleted_at: (/* @__PURE__ */ new Date()).toISOString() }).eq("conversation_id", conversationId).is("deleted_at", null);
  if (error) throw error;
}
export {
  clearPlan,
  createPlan,
  getCurrentPlan,
  listPlansForConversation,
  setPlanStatus
};
