import { z } from "zod";
const optionInputSchema = z.union([
  z.string().min(1),
  z.object({
    label: z.string().min(1),
    description: z.string().optional(),
    preview: z.string().optional()
  })
]);
function normalizeAskOptions(raw) {
  if (!raw) return void 0;
  return raw.map(
    (o) => typeof o === "string" ? { label: o } : { label: o.label, description: o.description, preview: o.preview }
  );
}
const USER_ASK_TYPES = [
  "confirm",
  "choice",
  "choice_many",
  "text",
  "secret",
  "notify"
];
const USER_ASK_TYPE_SET = new Set(USER_ASK_TYPES);
function recoverUserArgs(raw) {
  if (raw.type === void 0 && raw.questions === void 0 && typeof raw.action === "string" && USER_ASK_TYPE_SET.has(raw.action)) {
    const { action, ...rest } = raw;
    return {
      args: { ...rest, type: action },
      recoveredAlias: "action_to_type"
    };
  }
  return { args: raw, recoveredAlias: null };
}
const singleQuestionSchema = z.object({
  type: z.enum(USER_ASK_TYPES),
  question: z.string().optional(),
  header: z.string().max(12).optional(),
  options: z.array(optionInputSchema).optional(),
  context: z.string().optional(),
  message: z.string().optional(),
  actions: z.array(z.string().min(1)).optional(),
  level: z.enum(["info", "success", "warning", "error"]).optional(),
  allow_other: z.boolean().optional(),
  timeout_seconds: z.number().int().min(1).max(900).optional()
});
function validateSingle(v, ctx, pathPrefix) {
  const needsQuestion = v.type === "confirm" || v.type === "choice" || v.type === "choice_many" || v.type === "text" || v.type === "secret";
  if (needsQuestion && !v.question?.trim()) {
    ctx.addIssue({
      code: "custom",
      message: `question is required when type='${v.type}'`,
      path: [...pathPrefix, "question"]
    });
  }
  if (v.type === "notify" && !v.message?.trim()) {
    ctx.addIssue({
      code: "custom",
      message: "message is required when type='notify'",
      path: [...pathPrefix, "message"]
    });
  }
  if ((v.type === "choice" || v.type === "choice_many") && (!v.options || v.options.length < 2)) {
    ctx.addIssue({
      code: "custom",
      message: `options must have at least 2 entries when type='${v.type}'`,
      path: [...pathPrefix, "options"]
    });
  }
}
const userArgsSchema = z.object({
  // Single-question fields (omit when using batched form)
  type: z.enum(USER_ASK_TYPES).optional(),
  question: z.string().optional(),
  header: z.string().max(12).optional(),
  options: z.array(optionInputSchema).optional(),
  context: z.string().optional(),
  message: z.string().optional(),
  actions: z.array(z.string().min(1)).optional(),
  level: z.enum(["info", "success", "warning", "error"]).optional(),
  allow_other: z.boolean().optional(),
  timeout_seconds: z.number().int().min(1).max(900).optional(),
  // Batched form (mutually exclusive with everything above)
  questions: z.array(singleQuestionSchema).min(1).max(4).optional()
}).superRefine((v, ctx) => {
  const isBatch = !!v.questions && v.questions.length > 0;
  if (isBatch) {
    const stray = Object.entries(v).find(
      ([k, val]) => k !== "questions" && val !== void 0
    );
    if (stray) {
      ctx.addIssue({
        code: "custom",
        message: `When using the batched form, only \`questions\` may be set. Saw \`${stray[0]}\`.`,
        path: [stray[0]]
      });
    }
    v.questions?.forEach((q, i) => validateSingle(q, ctx, ["questions", i]));
    return;
  }
  if (!v.type) {
    ctx.addIssue({
      code: "custom",
      message: "Either `type` (single question) or `questions[]` (batched) is required",
      path: ["type"]
    });
    return;
  }
  validateSingle(v, ctx, []);
});
function isBatchedUserArgs(args) {
  return !!args.questions && args.questions.length > 0;
}
const updatePlanArgsSchema = z.object({
  title: z.string().optional(),
  steps: z.array(z.string().min(1)).min(1).max(40).optional(),
  // Aidream variants emit `approach` instead of `steps` — accept both.
  approach: z.array(z.string().min(1)).min(1).max(40).optional(),
  domains: z.array(z.string()).optional(),
  reasoning: z.string().optional(),
  estimated_minutes: z.number().int().positive().max(240).optional(),
  timeout_seconds: z.number().int().positive().max(15 * 60).optional()
}).refine((v) => v.steps != null || v.approach != null, {
  message: "either steps or approach is required"
});
const requestTakeoverArgsSchema = z.object({
  reason: z.string().min(1),
  expected_action: z.string().optional(),
  instructions: z.string().optional(),
  // tab_id matches the DB contract (browser surfaces use it; the web app ignores it).
  tab_id: z.string().optional(),
  timeout_seconds: z.number().int().min(1).max(900).optional()
});
const taskItemInputSchema = z.object({
  title: z.string().min(1).max(200),
  status: z.enum(["pending", "in_progress", "done", "blocked", "skipped"]).optional(),
  note: z.string().max(500).nullable().optional()
});
const userTodosArgsSchema = z.object({
  action: z.enum([
    "add",
    "list",
    "update",
    "remove",
    "mark_done",
    "clear_done"
  ]),
  title: z.string().min(1).max(200).optional(),
  context: z.string().max(300).nullable().optional(),
  due: z.string().max(80).nullable().optional(),
  id: z.string().optional(),
  silent: z.boolean().optional(),
  done: z.boolean().optional()
});
const googleEmailSendArgsSchema = z.object({
  to: z.string().min(3).max(320),
  cc: z.array(z.string()).max(20).optional(),
  subject: z.string().min(1).max(998),
  body: z.string().min(1).max(1e5)
});
const EMPTY_ASK_RESPONSE = {
  answer: null,
  selected: null,
  confirmed: null,
  action: null,
  freeform: null,
  additional_instructions: null,
  wrote_instead: false,
  data: null,
  cancelled: false,
  timed_out: false
};
export {
  EMPTY_ASK_RESPONSE,
  googleEmailSendArgsSchema,
  isBatchedUserArgs,
  normalizeAskOptions,
  recoverUserArgs,
  requestTakeoverArgsSchema,
  updatePlanArgsSchema,
  userArgsSchema,
  userTodosArgsSchema
};
