import { db } from "./supabase-typed.js";
import { writeOne } from "@ai-matrx/data/db";
import { ensureOrgId } from "../../../host/org.js";
async function listTasks(conversationId) {
  const { data, error } = await db.schema("chat").from("agent_task").select("*").eq("conversation_id", conversationId).is("deleted_at", null).order("position", { ascending: true });
  if (error) throw error;
  return data ?? [];
}
async function addTasks(inputs) {
  if (inputs.length === 0) return [];
  const first = inputs[0];
  const { data: existing } = await db.schema("chat").from("agent_task").select("position").eq("conversation_id", first.conversation_id).order("position", { ascending: false }).limit(1);
  const startPos = (existing?.[0]?.position ?? -1) + 1;
  const organizationId = await ensureOrgId(void 0);
  const rows = inputs.map((input, idx) => ({
    organization_id: organizationId,
    conversation_id: input.conversation_id,
    title: input.title,
    status: input.status ?? "pending",
    note: input.note ?? null,
    position: input.position ?? startPos + idx,
    creator_kind: input.creator_kind ?? "agent",
    plan_id: input.plan_id ?? null
  }));
  const { data, error } = await db.schema("chat").from("agent_task").insert(rows).select("*");
  if (error) throw error;
  return data ?? [];
}
async function updateTask(id, patch) {
  const { data, error } = await db.schema("chat").from("agent_task").update(patch).eq("id", id).select("*").maybeSingle();
  if (error) throw error;
  return data ?? null;
}
function archivedNow() {
  return { deleted_at: (/* @__PURE__ */ new Date()).toISOString() };
}
async function removeTask(id) {
  await writeOne(
    db.schema("chat").from("agent_task").update(archivedNow()).eq("id", id).is("deleted_at", null).select("id"),
    { action: "delete", noun: "task" }
  );
}
async function reorderTasks(conversationId, orderedIds) {
  for (let i = 0; i < orderedIds.length; i++) {
    await writeOne(
      db.schema("chat").from("agent_task").update({ position: i }).eq("id", orderedIds[i]).eq("conversation_id", conversationId).select("id"),
      { action: "move", noun: "task" }
    );
  }
  return listTasks(conversationId);
}
async function clearCompletedTasks(conversationId) {
  const { data, error } = await db.schema("chat").from("agent_task").update(archivedNow()).eq("conversation_id", conversationId).eq("status", "done").is("deleted_at", null).select("id");
  if (error) throw error;
  return (data ?? []).map((r) => r.id);
}
async function clearAllTasks(conversationId) {
  const { error } = await db.schema("chat").from("agent_task").update(archivedNow()).eq("conversation_id", conversationId).is("deleted_at", null);
  if (error) throw error;
}
export {
  addTasks,
  clearAllTasks,
  clearCompletedTasks,
  listTasks,
  removeTask,
  reorderTasks,
  updateTask
};
