import { EMPTY_ASK_RESPONSE } from "../tools/schemas.js";
import { createPlan, setPlanStatus } from "../service/agent-plan.service.js";
import { addTasks } from "../service/agent-task.service.js";
import {
  enqueuePendingAsk,
  resolvePendingAsk,
  sweepPendingAsks
} from "../redux/pending-asks.slice.js";
import {
  registerAskResolver,
  expireAskByCallId
} from "../redux/ask-resolver-registry.js";
import { upsertPlan } from "../redux/agent-lists.slice.js";
const updatePlanHandler = {
  name: "update_plan",
  async run(args, ctx) {
    const { callId, conversationId, dispatch } = ctx;
    const steps = args.steps ?? args.approach ?? [];
    const title = args.title ?? "Plan";
    let planRow = null;
    try {
      planRow = await createPlan({
        conversation_id: conversationId,
        title,
        steps,
        reasoning: args.reasoning ?? null,
        domains: args.domains ?? null,
        estimated_minutes: args.estimated_minutes ?? null
      });
      dispatch(upsertPlan(planRow));
    } catch (e) {
      console.error("[update_plan] failed to persist proposed plan", e);
    }
    const expiresAtMs = typeof args.timeout_seconds === "number" ? Date.now() + args.timeout_seconds * 1e3 : void 0;
    dispatch(
      enqueuePendingAsk({
        callId,
        conversationId,
        toolName: "update_plan",
        kind: "plan_approval",
        question: "Approve this plan?",
        options: [{ label: "Approve" }, { label: "Reject" }],
        plan: {
          title,
          steps,
          reasoning: args.reasoning,
          estimated_minutes: args.estimated_minutes
        },
        expiresAtMs,
        status: "pending",
        createdAtMs: Date.now()
      })
    );
    const response = await new Promise(
      (resolve) => {
        registerAskResolver(callId, resolve);
        if (expiresAtMs) {
          const ms = expiresAtMs - Date.now();
          if (ms > 0) {
            setTimeout(() => expireAskByCallId(callId), ms);
          } else {
            resolve({ ...EMPTY_ASK_RESPONSE, timed_out: true });
          }
        }
      }
    );
    dispatch(resolvePendingAsk({ callId, conversationId }));
    queueMicrotask(() => {
      setTimeout(() => dispatch(sweepPendingAsks(conversationId)), 250);
    });
    if (response.cancelled || response.timed_out) {
      return {
        ok: true,
        plan: planRow ? {
          id: planRow.id,
          title: planRow.title,
          steps: planRow.steps,
          status: planRow.status,
          reasoning: planRow.reasoning
        } : null,
        status: planRow?.status ?? null,
        cancelled: response.cancelled,
        timed_out: response.timed_out
      };
    }
    const approved = response.confirmed === true || response.selected?.[0] === "Approve" || response.action === "Approve";
    if (!planRow) {
      return {
        ok: false,
        plan: null,
        status: null,
        cancelled: false,
        timed_out: false
      };
    }
    const nextStatus = approved ? "approved" : "rejected";
    let finalRow = planRow;
    try {
      finalRow = await setPlanStatus(planRow.id, nextStatus);
      dispatch(upsertPlan(finalRow));
    } catch (e) {
      console.error("[update_plan] setPlanStatus failed", e);
    }
    if (approved && steps.length > 0) {
      try {
        await addTasks(
          steps.map((title2) => ({
            conversation_id: conversationId,
            title: title2,
            status: "pending",
            creator_kind: "agent",
            plan_id: planRow.id
          }))
        );
      } catch (e) {
        console.error(
          "[update_plan] failed to auto-populate tasks from plan steps",
          e
        );
      }
    }
    return {
      ok: true,
      plan: {
        id: finalRow.id,
        title: finalRow.title,
        steps: finalRow.steps,
        status: finalRow.status,
        reasoning: finalRow.reasoning
      },
      status: finalRow.status,
      cancelled: false,
      timed_out: false
    };
  }
};
export {
  updatePlanHandler
};
