import { db } from "./supabase-typed.js";
import { writeOne } from "@ai-matrx/data/db";
import { ensureOrgId } from "../../../host/org.js";
async function listUserTodos(conversationId) {
  const { data, error } = await db.schema("chat").from("user_todo").select("*").eq("conversation_id", conversationId).is("deleted_at", null).order("done", { ascending: true }).order("created_at", { ascending: true });
  if (error) throw error;
  return data ?? [];
}
async function addUserTodo(input) {
  const { data, error } = await db.schema("chat").from("user_todo").insert({
    // `created_by` is stamped by the `_stamp_actor` trigger — never client-set.
    // org-filter: write-target writes into the organization the person is working in; no list reads it
    organization_id: await ensureOrgId(void 0),
    conversation_id: input.conversation_id,
    title: input.title,
    context: input.context ?? null,
    due: input.due ?? null,
    done: false
  }).select("*").single();
  if (error) throw error;
  return data;
}
async function updateUserTodo(id, patch) {
  const { data, error } = await db.schema("chat").from("user_todo").update(patch).eq("id", id).select("*").maybeSingle();
  if (error) throw error;
  return data ?? null;
}
async function removeUserTodo(id) {
  await writeOne(
    db.schema("chat").from("user_todo").update({ deleted_at: (/* @__PURE__ */ new Date()).toISOString() }).eq("id", id).select("id"),
    { action: "archive", noun: "to-do" }
  );
}
async function clearDoneUserTodos(conversationId) {
  const { data, error } = await db.schema("chat").from("user_todo").update({ deleted_at: (/* @__PURE__ */ new Date()).toISOString() }).eq("conversation_id", conversationId).eq("done", true).is("deleted_at", null).select("id");
  if (error) throw error;
  return (data ?? []).map((r) => r.id);
}
export {
  addUserTodo,
  clearDoneUserTodos,
  listUserTodos,
  removeUserTodo,
  updateUserTodo
};
